import{_ as i,o as a,c as e,ak as d}from"./chunks/framework.DvrM7GBU.js";const C=JSON.parse('{"title":"OCR 证据使用规范","description":"","frontmatter":{},"headers":[],"relativePath":"OCR资料/OCR 证据使用规范.md","filePath":"OCR资料/OCR 证据使用规范.md","lastUpdated":1776864657000}'),r={name:"OCR资料/OCR 证据使用规范.md"};function o(c,l,h,n,s,t){return a(),e("div",null,[...l[0]||(l[0]=[d('<h1 id="ocr-证据使用规范" tabindex="-1">OCR 证据使用规范 <a class="header-anchor" href="#ocr-证据使用规范" aria-label="Permalink to “OCR 证据使用规范”">​</a></h1><p>一句话摘要：这是一份面向维护者、研究者和 AI 检索系统的 OCR 证据使用规则页，目的不是让所有文档都堆原文，而是让“截图证据 → OCR 文本 → 专题结论”形成可回查、可降级、可维护的链路。</p><ul><li>适合对象：维护者、研究者、AI 检索系统、需要查证据的进阶玩家</li><li>当前状态：已整理</li><li>可信度：<code>[已确认]</code></li><li>关联文档：<code>docs/OCR资料/OCR资料导航.md</code>、<code>docs/OCR资料/OCR 证据链说明.md</code>、<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li></ul><h2 id="这页解决什么问题" tabindex="-1">这页解决什么问题 <a class="header-anchor" href="#这页解决什么问题" aria-label="Permalink to “这页解决什么问题”">​</a></h2><p>这页主要解决下面几类常见问题：</p><ul><li>什么情况下应该给专题页补 OCR 回链</li><li>OCR 原文应该怎么引用才不显得杂乱</li><li>OCR 有错字时该怎么处理</li><li>什么时候能写成“已确认”，什么时候只能写“高可信推断”</li><li>维护时怎样快速检查一页是否已经具备最小证据链</li></ul><h2 id="一、先分清-4-层内容" tabindex="-1">一、先分清 4 层内容 <a class="header-anchor" href="#一、先分清-4-层内容" aria-label="Permalink to “一、先分清 4 层内容”">​</a></h2><p>在这个资料库里，建议始终把下面 4 层区分开：</p><ol><li><p>原始截图层</p><ul><li>是最底层证据源</li><li>价值最高，但不方便全文检索</li></ul></li><li><p>OCR 文本层</p><ul><li>是把截图转成可搜索文本的中间层</li><li>方便引用，但可能存在识别误差</li></ul></li><li><p>编号映射层</p><ul><li>用来把图片编号、OCR 文档、专题文档串起来</li><li>是最关键的追踪层</li></ul></li><li><p>专题归纳层</p><ul><li>是读者最常看的结论页</li><li>不应假装自己就是原始证据，而应能回查到底层</li></ul></li></ol><h2 id="二、推荐的最小回链格式" tabindex="-1">二、推荐的最小回链格式 <a class="header-anchor" href="#二、推荐的最小回链格式" aria-label="Permalink to “二、推荐的最小回链格式”">​</a></h2><p>高价值专题页，至少建议补下面这三项：</p><ul><li>来源截图编号：<code>若干编号</code></li><li>对应 OCR 文档：<code>某个 OCR 转写页路径</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li></ul><p>推荐写法示例：</p><ul><li>来源截图编号：<code>105506, 105510, 110352</code></li><li>对应 OCR 文档：<code>docs/OCR资料/引擎更新截图转文本.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li></ul><p>如果暂时拿不准编号是否精确齐全，也可以先写成“已定位到 OCR 文档，但编号仍待继续细化”，不要假装已经完整。</p><h2 id="三、什么页面必须优先补-ocr-回链" tabindex="-1">三、什么页面必须优先补 OCR 回链 <a class="header-anchor" href="#三、什么页面必须优先补-ocr-回链" aria-label="Permalink to “三、什么页面必须优先补 OCR 回链”">​</a></h2><p>优先级建议如下：</p><h3 id="第一优先级" tabindex="-1">第一优先级 <a class="header-anchor" href="#第一优先级" aria-label="Permalink to “第一优先级”">​</a></h3><ul><li>结论密度高的专题页</li><li>会被频繁引用的总览页</li><li>涉及版本变化、联机、UI、广播、数据结构的核心页</li></ul><h3 id="第二优先级" tabindex="-1">第二优先级 <a class="header-anchor" href="#第二优先级" aria-label="Permalink to “第二优先级”">​</a></h3><ul><li>项目设计类专题页</li><li>容易被误读为“官方定论”的归纳页</li><li>对外展示时高频使用的解释页</li></ul><h3 id="第三优先级" tabindex="-1">第三优先级 <a class="header-anchor" href="#第三优先级" aria-label="Permalink to “第三优先级”">​</a></h3><ul><li>导航页</li><li>路线页</li><li>维护说明页</li></ul><p>说明：</p><ul><li>导航页通常不需要逐段补证据编号</li><li>但导航页应该把读者引向有证据链的正文页</li></ul><h2 id="四、如何处理-ocr-错字" tabindex="-1">四、如何处理 OCR 错字 <a class="header-anchor" href="#四、如何处理-ocr-错字" aria-label="Permalink to “四、如何处理 OCR 错字”">​</a></h2><p>OCR 文本不是圣旨，它只是中间层。</p><p>建议规则：</p><ul><li>如果 OCR 文本有明显错字，但结合上下文可判断原意，可以在专题页中使用规范术语表达。</li><li>如果 OCR 文本含义模糊，不能直接强行下结论，应降级为 <code>[待验证]</code>。</li><li>如果 OCR 错字会影响关键判断，优先回看截图语境，而不是只看转写文本。</li></ul><p>不要做的事：</p><ul><li>不要把 OCR 错字直接当成正式术语写进术语表</li><li>不要把模糊文本硬写成“引擎已明确说明”</li><li>不要因为 OCR 看起来像某个词，就跳过截图核对</li></ul><h2 id="五、结论等级怎么跟证据层对应" tabindex="-1">五、结论等级怎么跟证据层对应 <a class="header-anchor" href="#五、结论等级怎么跟证据层对应" aria-label="Permalink to “五、结论等级怎么跟证据层对应”">​</a></h2><h3 id="可以标成-已确认-的情况" tabindex="-1">可以标成 <code>[已确认]</code> 的情况 <a class="header-anchor" href="#可以标成-已确认-的情况" aria-label="Permalink to “可以标成 [已确认] 的情况”">​</a></h3><p>通常至少满足以下之一：</p><ul><li>官方截图或更新说明直接明确写出</li><li>多张截图与 OCR 原文能稳定互相印证</li><li>文档中的说法基本属于“转述原文”，而不是额外推演</li></ul><h3 id="更适合标成-高可信推断-的情况" tabindex="-1">更适合标成 <code>[高可信推断]</code> 的情况 <a class="header-anchor" href="#更适合标成-高可信推断-的情况" aria-label="Permalink to “更适合标成 [高可信推断] 的情况”">​</a></h3><p>通常是：</p><ul><li>多来源材料指向同一结构规律</li><li>但原始资料没有逐字明确说到这句话</li><li>或专题结论里包含了整理者的抽象归纳</li></ul><h3 id="应标成-待验证-的情况" tabindex="-1">应标成 <code>[待验证]</code> 的情况 <a class="header-anchor" href="#应标成-待验证-的情况" aria-label="Permalink to “应标成 [待验证] 的情况”">​</a></h3><p>通常是：</p><ul><li>只有零碎截图线索</li><li>OCR 本身有歧义</li><li>不同版本间可能存在差异</li><li>还缺足够案例或实测支持</li></ul><h2 id="六、专题页里推荐怎么放证据说明" tabindex="-1">六、专题页里推荐怎么放证据说明 <a class="header-anchor" href="#六、专题页里推荐怎么放证据说明" aria-label="Permalink to “六、专题页里推荐怎么放证据说明”">​</a></h2><p>推荐放在头部元数据区附近，或放在文末“证据与来源”小节。</p><h3 id="头部简式写法" tabindex="-1">头部简式写法 <a class="header-anchor" href="#头部简式写法" aria-label="Permalink to “头部简式写法”">​</a></h3><ul><li>来源类型：官方更新 + 官方教程 + OCR 转写</li><li>证据等级：多来源交叉归纳</li><li>来源截图编号：<code>105506, 105510, 110352</code></li><li>对应 OCR 文档：<code>docs/OCR资料/引擎更新截图转文本.md</code></li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li></ul><h3 id="文末详式写法" tabindex="-1">文末详式写法 <a class="header-anchor" href="#文末详式写法" aria-label="Permalink to “文末详式写法”">​</a></h3><p>可增加：</p><ul><li>哪个结论主要来自哪类材料</li><li>哪些部分是直接证据</li><li>哪些部分是归纳解释</li><li>哪些地方仍需要补更多截图</li></ul><h2 id="七、维护时的快速判断标准" tabindex="-1">七、维护时的快速判断标准 <a class="header-anchor" href="#七、维护时的快速判断标准" aria-label="Permalink to “七、维护时的快速判断标准”">​</a></h2><p>如果一页满足下面大部分条件，就已经具备“最小可回查性”：</p><ul><li>有清晰的一句话摘要</li><li>有当前状态和可信度</li><li>有来源类型说明</li><li>有至少一个 OCR 文档回链</li><li>有映射表入口</li><li>关键结论区分了“已确认 / 高可信推断 / 待验证”</li></ul><h2 id="八、常见错误" tabindex="-1">八、常见错误 <a class="header-anchor" href="#八、常见错误" aria-label="Permalink to “八、常见错误”">​</a></h2><h3 id="错误-1-把所有原文都塞进专题正文" tabindex="-1">错误 1：把所有原文都塞进专题正文 <a class="header-anchor" href="#错误-1-把所有原文都塞进专题正文" aria-label="Permalink to “错误 1：把所有原文都塞进专题正文”">​</a></h3><p>后果：</p><ul><li>阅读体验会很差</li><li>结论层和证据层混在一起</li></ul><h3 id="错误-2-只写-来源于-ocr-但不给路径" tabindex="-1">错误 2：只写“来源于 OCR”但不给路径 <a class="header-anchor" href="#错误-2-只写-来源于-ocr-但不给路径" aria-label="Permalink to “错误 2：只写“来源于 OCR”但不给路径”">​</a></h3><p>后果：</p><ul><li>实际上无法回查</li><li>AI 和维护者都很难继续接力</li></ul><h3 id="错误-3-有-ocr-文本就直接写成已确认" tabindex="-1">错误 3：有 OCR 文本就直接写成已确认 <a class="header-anchor" href="#错误-3-有-ocr-文本就直接写成已确认" aria-label="Permalink to “错误 3：有 OCR 文本就直接写成已确认”">​</a></h3><p>后果：</p><ul><li>容易忽略 OCR 误识别和上下文缺失</li></ul><h3 id="错误-4-专题里大量强结论-但没有编号或映射入口" tabindex="-1">错误 4：专题里大量强结论，但没有编号或映射入口 <a class="header-anchor" href="#错误-4-专题里大量强结论-但没有编号或映射入口" aria-label="Permalink to “错误 4：专题里大量强结论，但没有编号或映射入口”">​</a></h3><p>后果：</p><ul><li>读者无法判断哪些是原文，哪些是整理者推演</li></ul><h2 id="九、推荐维护顺序" tabindex="-1">九、推荐维护顺序 <a class="header-anchor" href="#九、推荐维护顺序" aria-label="Permalink to “九、推荐维护顺序”">​</a></h2><ol><li>先给高价值专题补“对应 OCR 文档”</li><li>再补“来源截图编号”</li><li>再补“对应映射表”</li><li>最后再细化每段结论的等级说明</li></ol><p>这样做比一开始追求逐段精确编号更稳，也更容易持续推进。</p><h2 id="十、关联阅读" tabindex="-1">十、关联阅读 <a class="header-anchor" href="#十、关联阅读" aria-label="Permalink to “十、关联阅读”">​</a></h2><ul><li><code>docs/OCR资料/OCR资料导航.md</code></li><li><code>docs/OCR资料/OCR 证据链说明.md</code></li><li><code>docs/维护与报告/维护检查清单.md</code></li><li><code>docs/总索引与导航/创游世界知识库总导航.md</code></li></ul>',69)])])}const O=i(r,[["render",o]]);export{C as __pageData,O as default};
